local carried

local function carriedModules()
    if carried ~= nil then
        return carried or nil
    end

    local EUI = _G.EllesmereUI

    if not (EUI and EUI.DecodeImportString) or not Installer:HasPayload("EllesmereUI") then
        return nil
    end

    local ok, payload = pcall(EUI.DecodeImportString, profileString)
    local addons = ok and type(payload) == "table" and type(payload.data) == "table" and payload.data.addons

    carried = (type(addons) == "table" and next(addons) ~= nil) and addons or false

    return carried or nil
end

local function modules()
    local EUI = _G.EllesmereUI
    local map = EUI and EUI._ADDON_DB_MAP

    if not map then
        return {}
    end

    local exists = C_AddOns and C_AddOns.DoesAddOnExist
    local inString = carriedModules()
    local out = {}

    for _, entry in ipairs(map) do
        local host = entry.hostAddon or entry.folder
        local installed = not exists or exists(host)
        local bundled = not inString or inString[entry.canon or entry.folder] ~= nil

        if installed and bundled then
            out[#out + 1] = { folder = entry.folder, display = entry.display }
        end
    end

    return out
end


local chosen = {}
local function seedChosen(list)
    local remembered = Installer.db.euiModules

    wipe(chosen)

    for _, module in ipairs(list) do
        chosen[module.folder] = (remembered == nil) or (remembered[module.folder] and true or false)
    end
end

local function excluded()
    local disable

    for folder, on in pairs(chosen) do
        if not on then
            disable = disable or {}
            disable[#disable + 1] = folder
        end
    end

    return disable
end

local columns, rowHeight, gutter = 3, 22, 12
local topPad = 14

local function render(def, content)
    local list = modules()

    seedChosen(list)

    if #list == 0 then
        return
    end

    local available = content:GetWidth()

    if not available or available < 100 then
        available = 470 -- pre-layout fallback; the content box is 470 wide
    end

    local width = math.floor((available - gutter * (columns - 1)) / columns)

    for i, module in ipairs(list) do
        local column = (i - 1) % columns
        local line = math.floor((i - 1) / columns)

        local row = Kit.Checkbox(content, module.display, width, rowHeight - 2, function(_, checked)
            chosen[module.folder] = checked
        end)
        PixelUtil.SetPoint(row, "TOPLEFT", content, "TOPLEFT", column * (width + gutter), -topPad - line * rowHeight)
        row:SetChecked(chosen[module.folder])
    end
end

local function import(def, payload, profileName)
    local EUI = _G.EllesmereUI

    if not (EUI and EUI.ImportProfileSilent) then
        return false, "EllesmereUI's installer API is not available"
    end

    local list = modules()

    if next(chosen) == nil then
        seedChosen(list)
    end

    local disable = excluded()

    if disable and #disable >= #list then
        return false, "no modules are selected"
    end

    local ok, err = EUI.ImportProfileSilent({
        importString = payload,
        profileName = profileName,
        disableAddons = disable,
        applyUIScale = false,
    })

    if not ok then
        return false, err
    end

    local keep = {}
    for folder, on in pairs(chosen) do
        if on then
            keep[folder] = true
        end
    end

    Installer.db.euiModules = keep

    return true
end

Installer:RegisterAddon({
    key = "EllesmereUI",
    title = "|cff0cd29fEllesmereUI|r",
    description = "EllesmereUI combines the most intuitive UI editor in WoW with extreme performance optimization and endless customization. Bring your UI to life like never before.",
    folder = "EllesmereUI",
    version = "1",
    needsReload = true,
    profile = profileString,
    render = render,
    apply = import,
})
